parameters.jsCode:
const body = $input.first().json.body;
const repo = body.repo || 'my-app';
const prTitle = body.prTitle || 'Pull Request';
const score = body.qualityScore || 85;
const grade = body.grade || 'B';
const statusColor = score >= 80 ? 3066993 : (score >= 60 ? 15844367 : 15158332);
const prUrl = body.prUrl || 'https://github.com';

const discordPayload = {
  username: 'AI Code Reviewer Bot',
  avatar_url: 'https://cdn-icons-png.flaticon.com/512/2111/2111432.png',
  embeds: [
    {
      title: `⚡ [CODE REVIEW] ${repo} - PR: ${prTitle}`,
      color: statusColor,
      description: `Kết quả rà soát tự động Pull Request:\n**Điểm chất lượng:** ${score}/100 (Hạng: **${grade}**)`,
      fields: [
        { name: 'Kho mã nguồn', value: repo, inline: true },
        { name: 'Số lỗi bảo mật', value: `${body.criticalCount || 0}`, inline: true },
        { name: 'Xem trên GitHub', value: `[Mở Pull Request](${prUrl})`, inline: true }
      ],
      footer: { text: 'Automated by AI Code Reviewer • Software Engineering Automation' },
      timestamp: new Date().toISOString()
    }
  ]
};

return {
  json: {
    discordWebhookUrl: body.discordWebhookUrl,
    discordPayload
  }
};

parameters.responseBody:
={
  "success": true,
  "message": "Đã gửi thông báo review PR thành công!"
}
